from django.core.management.base import BaseCommand
from django.contrib.auth.models import Group, Permission
from news.models import Category, Page


PUBLIC_PAGES = [
    ('About Cedarmond TV', 'about', 10, """<p>Cedarmond TV is a Kenyan digital news publication. We report on public affairs, business, counties, culture, technology and sport, with context for readers.</p><h2>Our approach</h2><p>We aim to publish accurate, clearly attributed reporting. We distinguish reporting from opinion, identify material uncertainty and correct significant errors when they are brought to our attention.</p><p>Read our <a href='/pages/editorial-standards/'>editorial standards</a> and <a href='/pages/corrections/'>corrections policy</a>. To contact the newsroom, use the <a href='/contact/'>contact form</a>.</p>"""),
    ('Editorial standards', 'editorial-standards', 20, """<p>These standards guide Cedarmond TV's reporting, editing, headlines, images and reader engagement.</p><h2>Accuracy and verification</h2><p>We check material facts against reliable sources, seek comment from people directly affected by serious allegations, and make clear when information is preliminary or disputed. A source's claim is not presented as an established fact without verification.</p><h2>Attribution and fairness</h2><p>We identify sources where it is safe and appropriate to do so. We do not knowingly present another publisher's reporting as our own. We give people a fair opportunity to respond to significant claims and include relevant context.</p><h2>Headlines, images and opinion</h2><p>Headlines should accurately represent the article. Images must be relevant and used with permission or a recorded lawful basis. Opinion and analysis should be clearly distinguished from straight news reporting.</p><h2>Conflicts and corrections</h2><p>Staff should disclose relevant conflicts to editors. We review credible complaints, correct material errors clearly and update articles when important facts change. Send a concern through our <a href='/pages/corrections/'>corrections page</a>.</p><h2>Reader comments</h2><p>Comments are moderated before publication. We may reject or remove spam, threats, hate, private personal information and unsubstantiated harmful allegations.</p>"""),
    ('Corrections and complaints', 'corrections', 30, """<p>Accuracy matters. If you believe a Cedarmond TV story contains a factual error, tell us so an editor can review it.</p><h2>How to request a correction</h2><p>Use the <a href='/contact/'>contact form</a> and select or write “Correction”. Include the story headline or link, the specific passage you believe is inaccurate, the correct information and any reliable supporting documents or sources. Please identify yourself and provide a way for the newsroom to follow up.</p><h2>What happens next</h2><p>We assess correction requests on their evidence and editorial significance. We may contact you for clarification or seek a response from other parties. If we confirm a material error, we will correct the story and, where appropriate, explain the change. Sending a request does not guarantee that we will make the change requested.</p><p>For privacy concerns, use the contact form and mark the message “Privacy/data request”.</p>"""),
    ('Advertising and sponsorships', 'advertising', 40, """<p>Cedarmond TV offers a limited number of direct image-advertising placements on the homepage and article pages. Placements are managed by the newsroom and are labelled as advertising.</p><h2>Enquiries</h2><p>For availability, artwork requirements, destination links and rates, contact us through the <a href='/contact/'>contact form</a> and select “Advertising enquiry”. Include your organisation, campaign dates and the page or audience you wish to reach. The newsroom will confirm availability and terms before anything is published.</p><h2>Editorial independence</h2><p>Paid placements are separate from newsroom coverage. Payment does not guarantee an article, favourable reporting or editorial influence. Advertisers are responsible for having the rights to submitted artwork and for the content and destination of their advertisements.</p><p>Advertisements link to third-party websites. Their privacy practices are governed by those websites.</p>"""),
    ('Privacy and data protection', 'privacy', 50, """<p><strong>Last updated: 11 November 2026.</strong> This notice explains how Cedarmond TV, a Cedarmond Enterprises publication, handles personal information when you use this website.</p><p>We collect information for specific newsroom and service purposes. We do not sell personal information and the current site does not use third-party behavioural advertising or analytics trackers.</p><h2>Information you provide</h2><ul><li><strong>Contact messages:</strong> your name, email address, subject and message, so the newsroom can respond to tips, corrections, advertising enquiries, privacy requests and feedback.</li><li><strong>Newsletter:</strong> if subscriptions are enabled, your email address and subscription/confirmation status. We send newsletter messages only after the requested confirmation process and you can unsubscribe using the link in each message.</li><li><strong>Reader comments:</strong> the display name and comment text you submit. Comments are held for moderation; if approved, your display name and comment become public alongside the story. Do not include confidential or sensitive personal information.</li></ul><h2>Technical and security information</h2><p>Necessary session and security mechanisms support form protection, short-lived rate limits, moderation and newsroom sign-in protection. The server may process connection information such as an IP address for abuse prevention and security. Saved-story preferences are stored in your own browser's local storage and are not synced to an account.</p><h2>How we use information</h2><p>We use contact details to handle the request you sent; newsletter details to deliver the briefing you requested; comment details to moderate and, if approved, publish your comment; and technical information to protect the site and prevent abuse. We do not use these details to build advertising profiles.</p><h2>Who may process it</h2><p>The site is hosted on an AWS virtual machine. If newsletter delivery is enabled, email addresses and message delivery data are processed by the SMTP service configured for Cedarmond TV. These providers process information to operate the service. Depending on provider location and configuration, processing may take place outside Kenya. The active email provider and processing region depend on the current deployment configuration; contact us if you need those details for a specific request.</p><p>Contact messages and newsroom records are accessible to authorised staff who need them to respond, moderate or operate the publication. Approved reader comments are visible to the public. When you follow an external link or share a story using another service, that service handles information under its own terms and privacy notice.</p><h2>Retention</h2><p>We keep contact messages while they are needed to respond, resolve and document the request, and longer only where a legal or security need requires it. Newsletter records are kept while a subscription is active; an unsubscribed email may be retained as a suppression record so it is not accidentally subscribed or mailed again. Comments are retained while needed for moderation and, if approved, as part of the published discussion. Email delivery records are retained for service operation and troubleshooting. We review information for deletion or anonymisation when it is no longer needed.</p><h2>Your choices and rights</h2><p>Depending on the circumstances and applicable law, you may request information about use, access to your personal information, correction of inaccurate or misleading information, deletion where permitted, or object to processing. Other rights may apply to particular processing. You can withdraw newsletter consent by using the unsubscribe link. To make a privacy request, use the <a href='/contact/'>contact form</a> and select “Privacy/data request”; include enough detail for us to locate the record. We may ask for reasonable information to verify your identity before acting.</p><p>You may also raise a concern with Kenya's <a href='https://www.odpc.go.ke/'>Office of the Data Protection Commissioner</a>. The Data Protection Act and related regulations govern applicable rights and obligations.</p><h2>Security and updates</h2><p>We use access controls, HTTPS and restricted service networking to reduce risk. No internet service can promise absolute security. We may update this notice when our practices or the law changes; the latest version will be published here.</p>"""),
    ('Cookie notice', 'cookies', 60, """<p><strong>Last updated: 11 November 2026.</strong> Cedarmond TV uses browser storage needed for site security and basic functions. The current site does not use analytics cookies or third-party behavioural advertising trackers.</p><h2>Cookies used by the site</h2><ul><li><strong>csrftoken:</strong> helps protect forms against cross-site request forgery.</li><li><strong>sessionid:</strong> may be set for a newsroom sign-in session. It is not used to track readers across other websites.</li><li><strong>messages:</strong> may briefly hold a signed status message after an action, such as confirmation that a contact form was received.</li></ul><p>These cookies support core functions and security. Blocking them may prevent forms or newsroom sign-in from working correctly.</p><h2>Browser storage</h2><p>If you choose “Save story”, the site stores that choice in local storage on your device. It is not a cookie, does not sync across devices and is not sent to our servers. Clear your browser's site data to remove saved-story choices.</p><h2>External services</h2><p>Story-sharing links and advertisements may take you to external services. If you open those services, they may set their own cookies or collect information under their own policies. Cedarmond TV does not control those services.</p><p>If we add analytics, personalised advertising or other non-essential tracking in future, we will update this notice and provide any choices required by applicable law before that processing begins.</p>"""),
    ('Terms of use', 'terms', 70, """<p><strong>Last updated: 11 November 2026.</strong> These terms apply when you use the Cedarmond TV website. By using the site, you agree to follow them and applicable law.</p><h2>Editorial content</h2><p>Articles are provided for general news and information. We work to keep reporting accurate and current, but facts may change and errors can occur. Contact us through the <a href='/pages/corrections/'>corrections page</a> if you identify a material factual issue.</p><h2>Copyright and permitted use</h2><p>Unless a story or image says otherwise, Cedarmond TV and its licensors retain rights in published text, photographs, graphics and branding. You may link to our public pages and quote short passages with clear attribution and a link. Do not republish full articles or reuse photographs without permission from the relevant rights holder.</p><h2>Reader submissions</h2><p>Do not submit unlawful, threatening, harassing, defamatory, spam or confidential material through comments or contact forms. You remain responsible for material you submit. Comments are reviewed before publication and may be edited for safety or rejected under our <a href='/pages/editorial-standards/'>editorial standards</a>.</p><h2>External links and advertising</h2><p>Links and advertisements may lead to services operated by others. Cedarmond TV does not control those sites and is not responsible for their content, services or privacy practices.</p><h2>Changes and availability</h2><p>We may update these terms and the site. We may change, suspend or remove a feature for editorial, security or operational reasons. The latest terms will be posted on this page.</p><h2>Contact</h2><p>Questions about these terms can be sent through our <a href='/contact/'>contact form</a>.</p>"""),
]


class Command(BaseCommand):
    help = 'Create newsroom roles, sections and initial public trust pages; no accounts or articles are created.'
    def handle(self,*args,**options):
        for index,name in enumerate(['Kenya','Politics','Counties','Business','Technology','Culture','Sports','Opinion']):
            Category.objects.get_or_create(slug=name.lower(),defaults={'name':name,'position':index})
        reporter,_ = Group.objects.get_or_create(name='Reporter')
        editor,_ = Group.objects.get_or_create(name='Editor')
        reporter.permissions.set(Permission.objects.filter(content_type__app_label='news',codename__in=['add_article','view_article','change_article','view_category','view_author','view_tag','view_mediaasset']))
        editor.permissions.set(Permission.objects.filter(content_type__app_label='news').exclude(content_type__model__in=['subscription','campaign','campaigndelivery']))
        for title,slug,position,body in PUBLIC_PAGES:
            Page.objects.get_or_create(slug=slug,defaults={'title':title,'position':position,'body':body,'published':True})
        self.stdout.write(self.style.SUCCESS('Newsroom roles, sections and initial public pages ready. Grant staff status and assign groups in admin.'))
